  push("\u0417\u0432\u0435\u0437\u0434\u0430 \u0443\u0447\u0451\u043D\u043E\u0441\u0442\u0438", [[5, 6, 8, 9, 8, 9, 11, 0, 2, 3][dm]], "\u0443\u043C, \u0443\u0447\u0451\u0431\u0430, \u044D\u043A\u0437\u0430\u043C\u0435\u043D\u044B, \u043F\u0438\u0441\u044C\u043C\u043E", "\u0431\u0435\u0437 \u043C\u0435\u0445\u0430\u043D\u0438\u043A\u0438 \u0432 \u043A\u043B\u0430\u0441\u0441\u0438\u043A\u0435 (KB 16)");
