  if (td.length) stars.push({ name: "\u041D\u0435\u0431\u0435\u0441\u043D\u0430\u044F \u0434\u043E\u0431\u0440\u043E\u0434\u0435\u0442\u0435\u043B\u044C", pos: td, sense: "\u0442\u0440\u0443\u0434\u043D\u043E\u0435 \u0441\u043C\u044F\u0433\u0447\u0430\u0435\u0442\u0441\u044F, \u043F\u043E\u043C\u043E\u0449\u044C \u043F\u0440\u0438\u0445\u043E\u0434\u0438\u0442 \u0432\u043E\u0432\u0440\u0435\u043C\u044F" });
  const yd = byStem(YUEDE);
